INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Meet Cute: Finding Love', 'Meet Cute: Finding Love is a heartfelt romance about Zak, a socially isolated man in his mid-30s who, on the advice of his therapist, begins exploring in-person activities to combat his loneliness. Despite some awkward starts, he eventually bonds with a group of fellow comic and anime fans, including Jessica, a woman who shares his love for Demon Slayer. What follows is a journey of self-discovery, as Zak learns that before he can fully open his heart to others, he must first confront his fears and embrace his own worth.' FROM games WHERE igdb_id = 337680 ON CONFLICT (game_id, language_code) DO NOTHING;
