INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Winnie-the-Pooh: Realm of Torment', 'Tricked by Winnie-the-Pooh, you must navigate a twisted maze filled with psychological tricks, demons, and sadistic challenges. Outsmart your tormentor, solve puzzles, and survive his pursuit. Reclaim your soul through multiple endings. Can you escape the clutches of this diabolical bear?' FROM games WHERE igdb_id = 253809 ON CONFLICT (game_id, language_code) DO NOTHING;
