INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chimera', 'Play as the mythological Chimera in this action-packed rogue-lite. Make your escape from a deadly tower filled with unrelenting enemies as you uncover its dark secrets. Enter this fantasy world and overcome intense challenges, find hidden lore, and discover the true reason behind your imprisonment.' FROM games WHERE igdb_id = 312718 ON CONFLICT (game_id, language_code) DO NOTHING;
