INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tamarindos Freaking Dinner', 'Tamarindos Freaking Dinner; first-person horror adventure game and the spiritual successor of Baobabs Mausoleum. The second game of the "Jacob Jazz''s Treelogy". A mix between A 90''s sitcom, Luigi''s Mansion & the tabletop game Clue! Featuring hilarious dialogue and stories in the style of the most famous graphic adventures, this is the tale of Macario Macabro, whom no one knew was already dead... On the day that he died.' FROM games WHERE igdb_id = 152108 ON CONFLICT (game_id, language_code) DO NOTHING;
