INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bpop', 'Bpop is a captivating pop shooter where players strategically link colored explosions to annihilate balls in a top-down view. With every 10,000 points, earn extra balls, while utilizing the L stick to move your launcher, R stick to aim the projectile, and the X button to fire. Master the art of chaining combos to achieve the major goal of obliterating all balls on screen and unlock endless fun in this arcade challenge.' FROM games WHERE igdb_id = 286809 ON CONFLICT (game_id, language_code) DO NOTHING;
