INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Visions of Mana', 'For the first time in over 15 years, a brand-new entry in the mainline Mana series arrives! Embark on a new adventure with Val, the newly appointed soul guard, as he sets off on a journey across the world to accompany his friend on her pilgrimage to the Tree of Mana. Experience action-packed gameplay and explore a vibrant semi-open 3D field, encountering fearsome foes and unlikely allies along the way.' FROM games WHERE igdb_id = 279636 ON CONFLICT (game_id, language_code) DO NOTHING;
