INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('math-genius-multiplication', 321483, '2024-10-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co91s7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar36rr.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Math Genius: Multiplication', 'Math Genius: Multiplication is a fun and educational game that challenges players with randomly generated multiplication problems. Players fill in the missing number in the equation by choosing one of three possible answers. Keep track of your progress with on-screen counters displaying your correct and incorrect answers. Perfect for sharpening math skills in a quick, engaging format!' FROM games WHERE igdb_id = 321483 ON CONFLICT (game_id, language_code) DO NOTHING;
