INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('meet-cute-falling-for-you', 337682, '2024-12-17', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9lr3.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scw18h.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Meet Cute: Falling for You', '"Falling for You" is a heartwarming and comedic story about Ian, a timid man in his mid-30s stuck in a rut, who reluctantly agrees to try rock climbing at the urging of his friend. Initially clumsy and out of his element, Ian discovers unexpected joy and resilience as he pushes himself out of his comfort zone. Along the way, he meets Helena, a confident and athletic climber who takes him under her wing. Through her guidance and their growing friendship, Ian faces physical and emotional challenges that lead him on a transformative journey of self-discovery, perseverance, and unexpected connections.' FROM games WHERE igdb_id = 337682 ON CONFLICT (game_id, language_code) DO NOTHING;
