INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('circle--3', 320435, '2024-10-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8zh5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar35z2.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Circle', '"Circle" is a fast-paced, addictive arcade-style game designed to test your reflexes, precision, and strategic thinking as you navigate a deceptively simple yet increasingly intense circular arena. At first glance, "Circle" may seem straightforward, but the challenge quickly escalates, drawing you into a thrilling loop of action, suspense, and quick decision-making. The primary objective is clear: collect as many points as possible to achieve the highest score, all while dodging the ever-present and multiplying threats of black dots that are relentlessly poised to end your run.
