INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Frogs', 'Frogs is a clicker game where you tap to collect a variety of frogs. You can obtain them every 2 hours or unlock unique ones from chests that you can obtain by clicking. Equip frogs to boost your score, trade them in the marketplace, and just collect them all. Dive into this adventure with us!' FROM games WHERE igdb_id = 318688 ON CONFLICT (game_id, language_code) DO NOTHING;
