INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('yet-another-climbing-game', 323422, '2024-11-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9cs0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar37dh.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yet Another Climbing Game', 'Yet Another Climbing Game is a punishing ascent, a twisted tribute to the agony of determination. You guide your climber with a single, clumsy mechanic, grappling upward with imprecise precision. That’s all there is. With persistence, you might find yourself soaring, stumbling, and sometimes hanging by a thread. Great mysteries and perhaps some reward await those daring (or foolish) enough to reach the top.' FROM games WHERE igdb_id = 323422 ON CONFLICT (game_id, language_code) DO NOTHING;
