INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Lust City 2', 'Embark on an exotic quest in "The Lust City 2"! Lead your crew through a steamy jungle, unlocking treasures and secrets of an ancient tribe. Craft your seductive harem in a thrilling adventure that will leave you breathless. Explore the lustful depths of the jungle – where danger meets desire!' FROM games WHERE igdb_id = 297356 ON CONFLICT (game_id, language_code) DO NOTHING;
