INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'El-Silbon', 'You wake up in the dead of night, haunted by a chilling, distant whistle that grows louder with every passing moment. It''s El Silbón, the legendary Venezuelan spirit of vengeance. Armed with only your wits and courage, you must unravel the mystery of the sound, gather tools to protect yourself, and perform ancient rituals to banish the Whistler before it claims your soul. Survive until dawn—if you can.' FROM games WHERE igdb_id = 391659 ON CONFLICT (game_id, language_code) DO NOTHING;
