INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('meet-cute-dice-and-destiny', 337683, '2024-12-17', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9lr4.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scw18m.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Meet Cute: Dice and Destiny', 'Johnson, a charming yet awkward board game enthusiast, begins working at Meeple Haven, a quirky game shop filled with colorful personalities. On his first day, he meets Vanessa, a shy and brilliant coworker with a passion for strategy games. Over time, their mutual love for gaming becomes a bridge to connection, though both are too nervous to express their growing feelings. When a planned staff game night dwindles to just the two of them, Johnson and Vanessa are left alone to bond over an epic match of Twilight Imperium. What starts as a casual evening of friendly competition evolves into something deeper as they realize how natural and fun it feels to spend time together. Through witty banter, shared laughs, and strategic moves, they begin to discover a connection that feels as exciting and unpredictable as rolling the perfect dice.' FROM games WHERE igdb_id = 337683 ON CONFLICT (game_id, language_code) DO NOTHING;
