INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Keep Looking', 'This is a nerve-wracking horror game that puts you in a dark, claustrophobic cave with a relentless creature. Survive by flashing your dying flashlight at the right moments—too soon or too late, and it’s over. You must keep an eye on the creature, but beware: staring too long is just as deadly.' FROM games WHERE igdb_id = 320582 ON CONFLICT (game_id, language_code) DO NOTHING;
