INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lock. Stock. And Hungry Pumpkins.', 'A fun indie western-style shooter where you must protect the townspeople from hordes of living pumpkins, find a hidden stash of gold, and uncover a farmers'' conspiracy. And, of course, there''s a betrayal involved too.' FROM games WHERE igdb_id = 330481 ON CONFLICT (game_id, language_code) DO NOTHING;
