INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '8 Ball: Reborn', 'And this time, your mission is to rescue the balls that got stuck in Snookyland. To do this, you need to face enemies, free them from their cages and collect golden tokens to unlock new levels. Each ball has a specific text that is displayed as soon as you rescue it, and when you return to the table, the rescued balls will be running free to celebrate freedom. When you complete the levels you unlock a painting, which will decorate the games room. Furthermore, if you collect all the golden chips and redeem all the balls, the table and game room will have a premium look.' FROM games WHERE igdb_id = 337783 ON CONFLICT (game_id, language_code) DO NOTHING;
