INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('playville', 366253, '2024-04-26', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coafhm.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar46mb.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'PlayVille', 'PlayVille is a pixel-style virtual social game where players can create customizable avatars, explore themed rooms, and interact with others worldwide through chat and live events. The game emphasizes social connection, creativity, and player-driven activities, offering over 10,000 furniture and costume items with regular new releases. Features include community contests, limited-time events, crafting, trading in a player-run marketplace, and exploration-based activities such as mining, fishing, and discovering hidden maps. Designed for players aged 13 and older, PlayVille combines social networking, customization, and casual MMO-style gameplay.' FROM games WHERE igdb_id = 366253 ON CONFLICT (game_id, language_code) DO NOTHING;
