INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Heroes Around Me', 'The Heroes Around Me tells a story of a family of 3: the hard-working and quiet father – Nan, his daughter Lili, and their pet dog Sesame. Players will experience the harshness and warmth in the simpler time of the 1990s, where lots of stories are untold.' FROM games WHERE igdb_id = 216918 ON CONFLICT (game_id, language_code) DO NOTHING;
