INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dollmaker', 'You wake up in an enormous room full of toys, in front of a misterious doll who''s lacking an eye. Soon, you discover that she''s your adversary in a macabre game, where you''ll have to demonstrate your doll-building skills to recover that part of yourself that you are missing. Just One Button.' FROM games WHERE igdb_id = 325919 ON CONFLICT (game_id, language_code) DO NOTHING;
