INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fluxed', 'You have invented a Time Watch, and traveled back in time to stop a bomb from detonating in a building in New York City, which started World War 3 and thus destroyed most of humanity. You get 4 loops of the same 2 minutes in which to find the 3 terrorists, find the code, and diffuse the bomb.' FROM games WHERE igdb_id = 301713 ON CONFLICT (game_id, language_code) DO NOTHING;
