INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('cursed-deal', 263807, '2024-10-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7deo.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2hhm.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cursed Deal', 'Cursed Deal is a Co-Op horror game like nothing you''ve ever experienced before. The game focuses on a dark vampire cult and features a villain who becomes cursed by betraying his cult on the night of the ritual and turns into a dark creature. The player who made a deal with the devil to get rid of the curse, must hunt down cult members and curse them into his side. Meanwhile, the cultists must complete the ritual and gain vampire powers on this challenging night. But beware! When humans turn into vampires, the roles will change and the creature hunt will begin. You never know who will win in this game where teams and roles will change, where the hunter can be the prey and the prey can be the hunter. Hide in the dark, use your special powers, and survive. Most importantly, don''t trust anyone. If your friend is cursed, he will turn into a creature and come after you.' FROM games WHERE igdb_id = 263807 ON CONFLICT (game_id, language_code) DO NOTHING;
