INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ace Attorney: The Final Trials', 'The Wright Anything Agency is back! Ace Attorney: The Final Trials is a fan game that takes place around half a year after Spirit of Justice.It acts as a sequel to the game, while also wrapping the series into a satisfying conclusion, and showing the rebirth of a new era for Phoenix Wright. Old and new faces alike will make an appearance in the Final Trials, and the Agency must face threats and dilemmas never seen before, including an underground organization scheming something very dubious....INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 366725 AND ge.slug = 'adventure' ON CONFLICT DO NOTHING;
