INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pagliaccionautas', 'This mechanism now in your hands is not exactly a game. I''m not going to say it isn''t a game; who am I to deny you the right to play? What I call a "cursed tool" is a synthetic studio. You take on the role of The Clown, an inquisitive and scathing fellow, determined to fulfill his mission: to form the perfect team of Paglaccionautas.' FROM games WHERE igdb_id = 332285 ON CONFLICT (game_id, language_code) DO NOTHING;
