INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '63 Days', 'A real-time tactics game from Destructive Creations taking place during WWII. The capital city of Poland, Warsaw, is under occupation of German forces, however there are groups of fearless people who are not afraid to face the enemy. 63 Days follows the steps of their previous game War Mongrels to deliver a Commandos-like game play set in the darkest days of human history.' FROM games WHERE igdb_id = 296541 ON CONFLICT (game_id, language_code) DO NOTHING;
