INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mini Airways', 'Mini Airways is a real-time management game where you play the role of an air traffic controller. Clear your aircraft to take off & land, direct them to the destination...and most of all don''t let them crash!! London, Tokyo, Shanghai... Test your ATC skills in distinctive maps around the globe!' FROM games WHERE igdb_id = 288116 ON CONFLICT (game_id, language_code) DO NOTHING;
