INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vacant''s Mine', 'So you’ve been arrested? No Problem! In Vacant’s Mine you can regain your freedom in just 7 Days! With a Mine Railway and a Plunger you’ll navigate through an abandoned mine to steal eggs. But beware of the Greebs, they have terrifying big mouths and razor sharp teeth!' FROM games WHERE igdb_id = 289918 ON CONFLICT (game_id, language_code) DO NOTHING;
