INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cute Fames Adventure', 'Cute Fames Adventure is an RPG game, more or less, where you play as this little creature that is called Fame, Fame is a normal looking humanoid creature that was turned into a dog by an experiment that only happened in their town. It is now your time to find out who did it and get him back to what he looked like!' FROM games WHERE igdb_id = 261214 ON CONFLICT (game_id, language_code) DO NOTHING;
