INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('im-on-observation-duty-7', 318811, '2024-10-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coaiu8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar35js.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'I''m on Observation Duty 7', 'The seventh installment of this beloved franchise presents you with six new levels, unique anomalies and insane intruders. As an employee of a mysterious organization your job is to monitor live surveillance camera footage and spot anomalies. Report any changes in the monitored rooms by clicking on the anomaly and selecting the type OR by choosing the right location and type of the anomaly from a menu to fix it. Anomalies appear at random so you never knows what is going to happen next. Too many active and unreported anomalies means death. Goal is to survive the entire night (from 00:00 to 06:00 in game time). You will need sharp eyes and good memory. The game contains psychological horror that mainly comes from making you paranoid about what has changed.' FROM games WHERE igdb_id = 318811 ON CONFLICT (game_id, language_code) DO NOTHING;
