INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Godzilla Kaiju Wars VR', 'This unattended VR motion attraction features five action packed levels of cinematic VR at a level of intensity and realism never seen before … anywhere. Godzilla Kaiju Wars VR is designed from the ground up to provide the most compelling experience while providing Raw Thrills’ trademark reliability and longevity. This highly interactive VR game boasts the Thrill-D NXT motion platform, patented force-feedback blasters, wind and vibration effects, 6 channel Earthshaker audio, and featuring the massive 2X65″ GigaScreen video displays – to suck in a never ending stream of players!' FROM games WHERE igdb_id = 307771 ON CONFLICT (game_id, language_code) DO NOTHING;
